/**
 * Expo config plugin: raise every CocoaPods target's IPHONEOS_DEPLOYMENT_TARGET
 * to at least MIN_IOS.
 *
 * Xcode 27 rejects deployment targets below iOS 15 as hard errors, and some
 * transitive pods (SDWebImage, lottie-ios, react-native-view-shot) still
 * declare 9.0–13.0. `ios/` is regenerated by `expo prebuild`, so the fix has
 * to live in a plugin rather than a hand-edited Podfile.
 */

const { withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const MIN_IOS = '15.1';
const MARKER = '# xangarro:min-pod-deployment-target';

const SNIPPET = `
    ${MARKER}
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |bc|
        current = bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current.nil? || Gem::Version.new(current) < Gem::Version.new('${MIN_IOS}')
          bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${MIN_IOS}'
        end
      end
    end
`;

function injectIntoPostInstall(podfile) {
  if (podfile.includes(MARKER)) return podfile;
  const anchor = /post_install do \|installer\|\n/;
  if (!anchor.test(podfile)) {
    throw new Error('with-min-pod-deployment-target: post_install block not found in Podfile');
  }
  return podfile.replace(anchor, (m) => m + SNIPPET);
}

module.exports = function withMinPodDeploymentTarget(config) {
  return withDangerousMod(config, [
    'ios',
    async (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'Podfile');
      fs.writeFileSync(file, injectIntoPostInstall(fs.readFileSync(file, 'utf8')));
      return cfg;
    },
  ]);
};

module.exports.injectIntoPostInstall = injectIntoPostInstall;
